<style>
@keyframes atlasEmbedSpin{to{transform:rotate(360deg)}}
.atlas-popup{position:fixed;inset:0;z-index:99999;display:none;align-items:center;justify-content:center;padding:20px;}
.atlas-popup.is-open{display:flex;}
.atlas-popup-backdrop{position:absolute;inset:0;background:rgba(15,23,42,.6);backdrop-filter:blur(2px);}
.atlas-popup-dialog{position:relative;width:400px;max-width:100%;background:#fff;border-radius:14px;box-shadow:0 24px 60px rgba(0,0,0,.28);overflow:hidden;}
.atlas-popup-close{position:absolute;top:8px;right:8px;z-index:3;width:32px;height:32px;line-height:1;font-size:22px;border:none;border-radius:50%;background:rgba(15,23,42,.06);color:#0f172a;cursor:pointer;padding:0;}
.atlas-popup-close:hover{background:rgba(15,23,42,.14);}
.atlas-embed-wrap{position:relative;width:100%;height:600px;max-height:calc(100vh - 60px);}
.atlas-embed-wrap iframe{border:none;width:100%;height:100%;max-width:100%;display:block;}
.atlas-embed-loader{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;background:#fff;z-index:2;transition:opacity .4s ease;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;}
.atlas-embed-spinner{width:44px;height:44px;border:4px solid #ecfdf5;border-top-color:#10b981;border-radius:50%;animation:atlasEmbedSpin .7s linear infinite;}
.atlas-embed-brand{font-size:12px;font-weight:700;letter-spacing:.12em;color:#059669;text-transform:uppercase;}
body.atlas-popup-lock{overflow:hidden;}
</style>
<script>
(function () {
	var ID = "6a901b9de104d95ba35cf740";
	var popup = document.getElementById("atlasPopup_" + ID);
	if (!popup) return;
	var wrap = document.getElementById("atlasWrap_" + ID);
	var frame = document.getElementById("atlasForm_" + ID);
	var loader = wrap ? wrap.querySelector(".atlas-embed-loader") : null;
	var loaded = false;
	var lastFocus = null;

	function buildSrc() {
		var base = frame.getAttribute("data-atlas-src") || "";
		var qs = window.location.search || "";
		if (qs.charAt(0) === "?") qs = qs.substring(1);
		var keep = [];
		qs.split("&").forEach(function (p) {
			var k = (p.split("=")[0] || "").toLowerCase();
			if (p.indexOf("=") > 0 && k.indexOf("utm_") === 0) keep.push(p);
		});
		return base + (keep.length ? ((base.indexOf("?") >= 0 ? "&" : "?") + keep.join("&")) : "");
	}

	function hideLoader() {
		if (!loader) return;
		loader.style.opacity = "0";
		setTimeout(function () { loader.style.display = "none"; }, 400);
	}

	function open(e) {
		if (e) e.preventDefault();
		lastFocus = document.activeElement;
		if (!loaded && frame) { frame.src = buildSrc(); loaded = true; }
		popup.classList.add("is-open");
		popup.setAttribute("aria-hidden", "false");
		document.body.classList.add("atlas-popup-lock");
		var btn = popup.querySelector(".atlas-popup-close");
		if (btn) btn.focus();
	}

	function close() {
		popup.classList.remove("is-open");
		popup.setAttribute("aria-hidden", "true");
		document.body.classList.remove("atlas-popup-lock");
		if (lastFocus && lastFocus.focus) lastFocus.focus();
	}

	document.addEventListener("click", function (e) {
		var opener = e.target.closest ? e.target.closest("[data-atlas-popup-open], .outComesButton") : null;
		if (opener) { open(e); return; }
		var closer = e.target.closest ? e.target.closest("[data-atlas-popup-close]") : null;
		if (closer && popup.contains(closer)) close();
	});

	document.addEventListener("keydown", function (e) {
		if ((e.key === "Escape" || e.keyCode === 27) && popup.classList.contains("is-open")) close();
	});

	window.addEventListener("message", function (ev) {
		var d = ev && ev.data;
		if (d && d.atlasWidget === "ready" && (!d.id || d.id === ID)) hideLoader();
	});

	if (frame) frame.addEventListener("load", hideLoader);
})();
</script>